// CSD_RATIONALE_BEGIN
// Root cause of 52% ceiling: The model generates syntactically-valid SQL but
// uses wrong identifiers — e.g., "model" instead of "model_list", "a.address_id"
// via table alias, "AS count" as a column alias — none of which are grounded in
// the provided schema. GroupBoostedConstrainedStep boosts schema tokens but
// cannot prevent choosing grammar-valid yet schema-ungrounded identifiers.
//
// Fix: Replace the inner GroupBoostedConstrainedStep loop with
// RegenerateUnitOnGroundingFailure, which:
//   (1) Generates tokens via dead-end-avoiding steps.
//   (2) Detects each completed schema symbol (table/column boundary).
//   (3) Checks if the identifier is grounded in the prompt context via
//       lm.FirstUngroundedIdentifierTokenIdx.
//   (4) On failure: rolls back to the last accepted checkpoint, persistently
//       penalizes the rejected identifier, and regenerates (up to maxRetries).
// This directly targets the 158/300 identifier-hallucination failures.
//
// Structure:
// Phase 1: 5-step preamble to emit "SQL: " prefix naturally.
// Phase 2: Force "<<" via OpenConstrainedSpan if not already inside.
// Phase 3: RegenerateUnitOnGroundingFailure with budget = remaining - 1,
//          maxRetries=5, maxRollbackBudget=50.
// Phase 4: CloseConstrainedSpan (if complete) else CloseSpanWithinBudget(80).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut so the implication
//   is vacuous throughout. The only true-flip is when RenderedEndsWith fires;
//   we simultaneously set currentConstrainedOut := [], and IsValidPrefix([])
//   holds by the method precondition. EOS break leaves insideConstrainedOut false.
//
// Phase 2 OpenConstrainedSpan: Only runs when !insideConstrainedOut. Postcondition
//   sets currentConstrainedOut := []; IsValidPrefix([]) holds by precondition.
//
// Phase 3 RegenerateUnitOnGroundingFailure: Postcondition guarantees
//   resultConstrained is always parser-valid. We assign
//   currentConstrainedOut := resultConstrained, so
//   parser.IsValidPrefix(currentConstrainedOut) is re-established. insideConstrainedOut
//   is unchanged (still true from Phase 2 or entry).
//
// Phase 4a CloseConstrainedSpan: Sets insideConstrainedOut := false, making the
//   implication vacuously true, and clears currentConstrainedOut := [].
//
// Phase 4b CloseSpanWithinBudget: Postcondition guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1
//   token (0 on EOS, 1 on non-EOS). Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<"
//   token. Net 1:1, invariant preserved.
//
// Phase 3: stablePrefix = generated[..|generated| - |currentConstrainedOut|].
//   After the call: generated = stablePrefix + resultConstrained.
//   |generated| = |stablePrefix| + |resultConstrained|
//              <= (|old_generated| - |currentConstrainedOut|) + sqlBudget
//              <= |old_generated| + sqlBudget
//              <= (|generatedPrefix| + old_steps) + sqlBudget
//              = |generatedPrefix| + new_steps.
//   The bound |resultConstrained| <= sqlBudget follows from the helper's
//   "at most +budget token-steps" cost contract: each step produces at most
//   one visible token, and rejected/rolled-back tokens still consume budget
//   without appearing in the output, so output length <= cost <= budget.
//
// Phase 4a: CloseConstrainedSpan +1 step, appends at most 1 ">>" token. ≤1:1.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated|
//   + closeBudget; steps += closeBudget; invariant preserved by transitivity.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded SQL via RegenerateUnitOnGroundingFailure
// Budget = remaining - 1 to reserve one step for the closing delimiter.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var sqlBudget: nat := remaining - 1;
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, sqlBudget, 5, 50
    );
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 80 {
      closeBudget := remaining;
    } else {
      closeBudget := 80;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

